head.script:
scwin.gDepCd = js_dep_cd;
scwin.gEmpNo = js_emp_no;
scwin.gLdMktTp = js_market;
scwin.gIsurCd;
scwin.gMktTp;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        scwin.hideDebugCtrls();
        $c.cm.PanelToGroupBox(panel_1);
        scwin.hideCorpEmpLabels("1"); // 코스닥 숨기기.

        await scwin.getParentValue();
        $c.cm.fn_com_isur(txb_ISUR_CD, txb_COM_NM);
        scwin.init();
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30601_BOND.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function() {
    rdo_MARKET_FLAG.setValue(scwin.gLdMktTp);
    const ISUR_CD = $c.stf.getQuery(frame.srcUrl, "ISUR_CD"); // 다른 페이지(기업정보조회)에서 넘어오는 경우 처리.
    // alert(frame.srcUrl);
    txb_ISUR_CD.setValue(ISUR_CD);
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30601_BOND.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name grd_List_OnClick
 * @description grd_List 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_List_OnClick = async function(row, colid) {
    try {
        await scwin.readChargeIssue(grd_List, row, colid);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30601_BOND.grd_List_OnClick" });
    }
};

/**
 * @method
 * @name dts_Grid_OnLoadError
 * @description dts_Grid 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Grid_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_Grid);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30601_BOND.dts_Grid_OnLoadError" });
    }
};

/**
 * @method
 * @name rdo_MARKET_FLAG_onselchange
 * @description rdo_MARKET_FLAG onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.rdo_MARKET_FLAG_onselchange = function() {
    try {
        scwin.hideCorpEmpLabels(rdo_MARKET_FLAG.getValue());
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30601_BOND.rdo_MARKET_FLAG_onselchange" });
    }
};

/**
 * @method
 * @name dts_Grid_OnLoadCompleted
 * @description dts_Grid 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Grid_OnLoadCompleted = async function(rowcount) {
    try {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
        await scwin.readChargeIssue(grd_List, 1, "ISUR_CD");
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30601_BOND.dts_Grid_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name btn_ISUR_CD_onclick
 * @description btn_ISUR_CD 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_ISUR_CD_onclick = function() {
    try {
        $c.cm.IsurcdSearchBond(txb_ISUR_CD, txb_COM_NM); // 2009.09.01 채권법인검색
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30601_BOND.btn_ISUR_CD_onclick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKeyPress
 * @description Grd com isur On Key Press 처리
 * @param {*} kcode kcode
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    try {
        if (kcode === '13') {
            $c.cm.fn_com_Confirm_set();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30601_BOND.Grd_com_isur_OnKeyPress" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnDblClick
 * @description Grd_com_isur 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    try {
        $c.cm.fn_com_Confirm_set();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30601_BOND.Grd_com_isur_OnDblClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnClick
 * @description Grd_com_isur 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnClick = function(row, colid) {
    try {
        Grd_com_isur.style.display = "";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30601_BOND.Grd_com_isur_OnClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnSetFocus
 * @description Grd com isur On Set Focus 처리
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnSetFocus = function() {
    try {
        stFocusGrid = true;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30601_BOND.Grd_com_isur_OnSetFocus" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKillFocus
 * @description Grd_com_isur 포커스 이탈 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKillFocus = function() {
    try {
        stFocusGrid = false;
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30601_BOND.Grd_com_isur_OnKillFocus" });
    }
};

/**
 * @method
 * @name MxDataSet_com_isur_OnFilter
 * @description Mx Data Set com isur On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    try {
        if (skw !== "" && foColum === "1") {
            f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
            f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
            if (f1.indexOf(skw) !== -1 || f2.indexOf(skw) !== -1) return true;

            else return false;
        } else {
            return true;
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30601_BOND.MxDataSet_com_isur_OnFilter" });
    }
};

/**
 * @method
 * @name txb_ISUR_CD_onblur
 * @description txb_ISUR_CD 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISUR_CD_onblur = function() {
    try {
        if (stFocusGrid === false) {
            Grd_com_isur.style.display = "none";
        }
        if (txb_ISUR_CD.getValue() === "") {
            txb_COM_NM.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30601_BOND.txb_ISUR_CD_onblur" });
    }
};

/**
 * @method
 * @name txb_ISUR_CD_onfocus
 * @description txb_ISUR_CD 포커스 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISUR_CD_onfocus = function() {
    try {
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30601_BOND.txb_ISUR_CD_onfocus" });
    }
};

/**
 * @method
 * @name txb_ISUR_CD_onkeyup
 * @description txb_ISUR_CD 키 입력 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISUR_CD_onkeyup = function() {
    try {
        if (txb_ISUR_CD.getValue() === "") {
            Grd_com_isur.style.display = "none";
        } else {
            if (window.event.keyCode === 40) {
                // 아래화살표눌렀을때 그리드로 포커스
                Grd_com_isur.focus();
            } else {
                $c.cm.fn_com_isur_nm(window.event.keyCode);
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30601_BOND.txb_ISUR_CD_onkeyup" });
    }
};

/**
 * @method
 * @name dts_Charge3_Info_OnLoadCompleted
 * @description dts_Charge3_Info 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Charge3_Info_OnLoadCompleted = function(rowcount) {
    try {
        scwin.changeFormat();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30601_BOND.dts_Charge3_Info_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Excel_onclick = async function() {
    try {
        if (grd_List2.getRowCount() < 1) {
            await $c.win.alert("저장할 정보가 없습니다.");
        } else {
            $c.stf.doLogSave("ULDSTF30601_BOND.xml", SCREN_PROCS_TP_CD_07, '');
            $c.data.downloadGridViewExcel(grd_List2, {fileName: "담당종목목록", type: "8"});
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30601_BOND.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name btn_Resume_onclick
 * @description 「변경이력」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Resume_onclick = function() {
    try {
        scwin.openResume();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30601_BOND.btn_Resume_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    const vMARKET_FLAG = rdo_MARKET_FLAG.getValue();
    let vISUR_CD = txb_ISUR_CD.getValue();
    const vLIST_STATUS = cmb_LIST_STATUS.getValue();
    const vISU_MKTP_TP_CD = cmb_ISU_MKTP_TP_CD.getValue(); // 시장구분

    if (js_market === '9') {
        // 관리자이면 채권팀으로 셋팅
        scwin.gDepCd = '2430';
    }
    url += "&MARKET_FLAG=" + vISU_MKTP_TP_CD;
    url += "&DEP_CD=" + scwin.gDepCd;
    url += "&ISUR_CD=" + vISUR_CD;
    url += "&EMP_NO=" + scwin.gEmpNo;
    url += "&ATTR_TP_CD=''";
    url += "&LIST_STATUS=" + vLIST_STATUS;
    url += "&SECU_GRP_ID=";
    url += "&SCREN_ID=" + "ULDSTF30601_BOND.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions = {
        id : "sbm_dts_Grid",
        action : "/ListedCompany.do",
        ref : "",
        target : "dts_Grid=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    if (dts_Grid.getRowCount() > 0) {
        await scwin.readChargeIssue(grd_List, 1, "ISUR_CD");
    } else {
        dts_Corp_Info.removeAll();
        dts_Krx_Emp_Info.removeAll();
        dts_Charge1_Info.removeAll();
        dts_Charge2_Info.removeAll();
        dts_Charge3_Info.removeAll();
    }
};

/**
 * @method
 * @name getChargeIssue
 * @description get Charge Issue 처리
 * @param {String} vISUR_CD vISUR_CD
 * @param {String} vMKT_TP_CD vMKT_TP_CD
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.getChargeIssue = async function(vISUR_CD, vMKT_TP_CD) {
    scwin.hideCorpEmpLabels(vMKT_TP_CD); // 코스닥 숨기기.

    url += "&SCREN_ID=" + "ULDSTF30601_BOND.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    // var url = "/ListedCompany.do?method=readChargeIssue&Flag=9&ISUR_CD=" + vISUR_CD;
    // 회사정보
    const sbmOptions = {
        id : "sbm_dts_Corp_Info",
        action : "/ListedCompany.do",
        ref : "",
        target : "dts_Corp_Info=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // 상공부 담당자 정보
    const sbmOptions2 = {
        id : "sbm_dts_Krx_Emp_Info",
        action : "/ListedCompany.do",
        ref : "",
        target : "dts_Krx_Emp_Info=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // 공시책임자(유, 코)
    const sbmOptions3 = {
        id : "sbm_dts_Charge1_Info",
        action : "/ListedCompany.do",
        ref : "",
        target : "dts_Charge1_Info=body.content",
        isProcessMsg : false
    };

    const sbmRtn3 = await $c.sbm.executeDynamic(sbmOptions3);
    // TODO Stage2: sbmRtn3 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // 공시담당자1, 공시담당자(유, 코)
    const sbmOptions4 = {
        id : "sbm_dts_Charge2_Info",
        action : "/ListedCompany.do",
        ref : "",
        target : "dts_Charge2_Info=body.content",
        isProcessMsg : false
    };

    const sbmRtn4 = await $c.sbm.executeDynamic(sbmOptions4);
    // TODO Stage2: sbmRtn4 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // 공시담당자2, 공시실무자(유, 코)
    const sbmOptions5 = {
        id : "sbm_dts_Charge3_Info",
        action : "/ListedCompany.do",
        ref : "",
        target : "dts_Charge3_Info=body.content",
        isProcessMsg : false
    };

    const sbmRtn5 = await $c.sbm.executeDynamic(sbmOptions5);
    // TODO Stage2: sbmRtn5 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const vStr = txb_Corp_CAP.getValue();
    if (vStr !== "") {
        vStr2 = $c.stf.FormatNumberEx(vStr);
        txb_Corp_CAP.setValue(vStr2);
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name getProvider
 * @description get Provider 처리
 * @returns {void}
 * @hidden N
 */
scwin.getProvider = function() {
    let url = frame.srcUrl;
    const arr = url.split("?");

    // alert(url +"     =      "+ arr);
    return (arr.length >= 1 ? $c.frame.path("../" + arr[1]) : undefined);
};

/**
 * @method
 * @name getParentValue
 * @description get Parent Value 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.getParentValue = async function() {
    const pvd = scwin.getProvider();
    if (pvd !== null) {
        scwin.gMktTp = pvd.scwin.gMktTp;
        scwin.gIsurCd = pvd.scwin.gIsurCd;
        if ($c.ut.trim(scwin.gIsurCd).length === 5) {
            await scwin.initSearch();
        }
    }
};

/**
 * @method
 * @name initSearch
 * @description 다른창에서 담당종목 조회를 클릭할때
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.initSearch = async function() {
    await scwin.getChargeIssue(scwin.gIsurCd, scwin.gMktTp);
};

/**
 * @method
 * @name readChargeIssue
 * @description read Charge Issue 처리
 * @param {String} GridID GridID
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.readChargeIssue = async function(GridID, row, colid) {
    if (row < 1) return;
    const objDataID = document.all(GridID.DataID); // 가져오는 방식이 좀 특이하다..

    let vISUR_CD = objDataID.getCellData(row, "ISUR_CD");
    const vMKT_TP_CD = objDataID.getCellData(row, "SPOT_ISU_TRD_MKT_TP_CD");
    await scwin.getChargeIssue(vISUR_CD, vMKT_TP_CD);
};

/**
 * @method
 * @name hideCorpEmpLabels
 * @description hide Corp Emp Labels 처리
 * @param {String} flag flag
 * @returns {void}
 * @hidden N
 */
scwin.hideCorpEmpLabels = function(flag) {
    const vStockLabels = new Array(lbl_CorpEmp2, lbl_CorpEmp3);
    const vKosdaqLabels = new Array(lbl_CorpEmp2_1, lbl_CorpEmp3_1);
    // 유가는 초기값을 가지고 있으므로 위치 이동은 없다.
    if (flag === "1") {
        // 유가. => 코스닥 숨기고 유가 위치이동 및 보이기.

        for (let i = 0; i < vKosdaqLabels.length; i++) {
            vKosdaqLabels[i].hide();
            vStockLabels[i].show("");
        }
    } else if (flag === "2") {
        // 코스닥.=>유가를 숨기고 코스닥 위치이동 및 보이기
        for (let i = 0; i < vStockLabels.length; i++) {
            $c.stf.SetWindowPos(vKosdaqLabels[i], vStockLabels[i].style.top, vStockLabels[i].style.left, vStockLabels[i].style.getStyle("width"), vStockLabels[i].style.getStyle("height"));
            $p.getComponentById(vStockLabels[i]).hide();
            vKosdaqLabels[i].show("");
        }
    }
};

/**
 * @method
 * @name hideDebugCtrls
 * @description hide Debug Ctrls 처리
 * @returns {void}
 * @hidden N
 */
scwin.hideDebugCtrls = function() {
    panel_mkt.hide();
    panel_debug.hide();
    if (js_market === "1") {
        btn_Resume.show("");
    } else {
        btn_Resume.hide();
    }
};

/**
 * @method
 * @name changeFormat
 * @description change Format 처리
 * @returns {void}
 * @hidden N
 */
scwin.changeFormat = function() {
    const ar = new Array(txb_Corp_RGHT_LIST_DD, txb_Chrg1_CHRG_DESIGN_DD, txb_Chrg1_WORK_TM, txb_Chrg2_WORK_TM, txb_Chrg3_WORK_TM, txb_Chrg2_CHRG_DESIGN_DD, txb_Chrg3_CHRG_DESIGN_DD);
    for (let i = 0; i < ar.length; i++) {
        const bfVal = ar[i].getValue();
        if (bfVal !== "") {
            const afVal = $c.stf.FormatDateEx(bfVal);
            // alert(bfVal + ", " + afVal);
            ar[i].setValue(afVal);
        }
    }
};

/**
 * @method
 * @name openResume
 * @description open Resume 처리
 * @returns {void}
 * @hidden N
 */
scwin.openResume = function() {
    $c.frame.path("../../").GWinOpen("ULDSTF30612", "/issueinfo/ULDSTF30612_BOND.gfm", "이력조회", 20, 20, 1270, 780, "");
};

/**
 * @method
 * @name FormatDateEx
 * @description Format Date Ex 처리
 * @param {String} str str
 * @returns {void}
 * @hidden N
 */
scwin.FormatDateEx = function(str) {
    if (str === "") return "";
    return str.substring(0, 4) + "-" + str.substring(4, 6) + "-" + str.substring(6, 8);
};
